import{_ as t,o as a,c as n,ae as o}from"./chunks/framework.vXWZTEWX.js";const m=JSON.parse('{"title":"Validation & Quality Assurance Report: TenderCheck-AI 📊","description":"","frontmatter":{},"headers":[],"relativePath":"VALIDATION_REPORT.md","filePath":"VALIDATION_REPORT.md"}'),i={name:"VALIDATION_REPORT.md"};function r(l,e,s,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="validation-quality-assurance-report-tendercheck-ai-📊" tabindex="-1">Validation &amp; Quality Assurance Report: TenderCheck-AI 📊 <a class="header-anchor" href="#validation-quality-assurance-report-tendercheck-ai-📊" aria-label="Permalink to &quot;Validation &amp; Quality Assurance Report: TenderCheck-AI 📊&quot;">​</a></h1><h2 id="_1-introduction-and-objectives" tabindex="-1">1. Introduction and Objectives <a class="header-anchor" href="#_1-introduction-and-objectives" aria-label="Permalink to &quot;1. Introduction and Objectives&quot;">​</a></h2><p>This document details the systematic validation process performed on the TenderCheck-AI engine to ensure legal and technical precision when extracting requirements from public tenders. The primary goal is to eliminate hallucinations and guarantee deterministic behavior through rigorous testing.</p><h2 id="_2-evaluation-methodology" tabindex="-1">2. Evaluation Methodology <a class="header-anchor" href="#_2-evaluation-methodology" aria-label="Permalink to &quot;2. Evaluation Methodology&quot;">​</a></h2><p>An observability and QA strategy has been implemented based on the <strong>LangSmith</strong> lifecycle.</p><h3 id="a-golden-dataset" tabindex="-1">A. Golden Dataset <a class="header-anchor" href="#a-golden-dataset" aria-label="Permalink to &quot;A. Golden Dataset&quot;">​</a></h3><ul><li><strong>Name</strong>: <code>TenderCheck_Official_Dataset_V2</code>.</li><li><strong>Content</strong>: 10 critical test cases extracted from real-world IT tender documents (pliegos).</li><li><strong>Purpose</strong>: Regression testing and prompt refinement within the LangSmith Playground.</li></ul><h3 id="b-environment-comparison-table" tabindex="-1">B. Environment Comparison Table <a class="header-anchor" href="#b-environment-comparison-table" aria-label="Permalink to &quot;B. Environment Comparison Table&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">LangSmith Playground (Lab)</th><th style="text-align:left;">LangSmith Tracing (Production)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Goal</strong></td><td style="text-align:left;">Prompt refinement &amp; rapid iteration.</td><td style="text-align:left;">Real-time user monitoring &amp; debugging.</td></tr><tr><td style="text-align:left;"><strong>Metric</strong></td><td style="text-align:left;">Automatic Score (Correctness).</td><td style="text-align:left;">Human feedback (Thumbs up/down).</td></tr><tr><td style="text-align:left;"><strong>Frequency</strong></td><td style="text-align:left;">During development phase.</td><td style="text-align:left;">Continuous with every execution.</td></tr></tbody></table><h2 id="_3-experimental-results" tabindex="-1">3. Experimental Results <a class="header-anchor" href="#_3-experimental-results" aria-label="Permalink to &quot;3. Experimental Results&quot;">​</a></h2><p>After refining the <em>System Prompt</em> (evolving into the &quot;Senior Tender Auditor&quot; persona), the following benchmarks were achieved:</p><ul><li><strong>Semantic Accuracy (Correctness)</strong>: 1.00 / 1.00 (100% Success Rate).</li><li><strong>Average Latency</strong>: &lt; 60 seconds for full document analysis.</li><li><strong>Token Efficiency</strong>: Optimized context windowing to reduce operational costs.</li></ul><h2 id="_4-visual-evidence" tabindex="-1">4. Visual Evidence <a class="header-anchor" href="#_4-visual-evidence" aria-label="Permalink to &quot;4. Visual Evidence&quot;">​</a></h2><blockquote><p><strong>Note for the Tribunal</strong>: Screenshots showing the experiments with the green <strong>1.00 Score</strong> and the execution traces from the Node.js backend are included in the main project report and within the <code>/assets</code> folder of this repository.</p></blockquote><h2 id="_5-quality-roadmap" tabindex="-1">5. Quality Roadmap <a class="header-anchor" href="#_5-quality-roadmap" aria-label="Permalink to &quot;5. Quality Roadmap&quot;">​</a></h2><ul><li><strong>Continuous Evaluation</strong>: Integration of automated regression tests into the CI/CD pipeline to validate the 100% accuracy mark on every deployment.</li></ul>',16)])])}const g=t(i,[["render",r]]);export{m as __pageData,g as default};
